// Prepare an input stream that contains a serialized std::string at the current position.
// Randomly decide if the serialized string will match the expected version to exercise both paths.
std::string expected = FUZZ_PARAM_STR();
std::string maybe_other = FUZZ_PARAM_STR();
bool make_match = (*FUZZ_PARAM(unsigned int) % 2) == 0;
std::string to_write = make_match ? expected : maybe_other;

std::ostringstream out_buf;
// Use dlib's serialize for std::string so the stream contains a valid serialized string object.
try {
    dlib::serialize(to_write, out_buf);
} catch (const dlib::serialization_error&) {
    // Underlying stream or serialization failure; treat as harness error.
    FUZZ_BAIL();
}

std::string payload = out_buf.str();
std::istringstream in(payload);

// Call the target: will throw dlib::serialization_error if versions don't match.
try {
    dlib::check_serialized_version(expected, in);
} catch (const dlib::serialization_error&) {
    // Mismatch or bad stream is an expected API error; bail to end this test case cleanly.
    FUZZ_BAIL();
}
// Validation: On success, the stream advanced past the serialized version string. We don't assert here.
// OK

// Use a fuzz-generated filename which points to a file filled with random data.
const char* fname = FUZZ_PARAM_FILENAME();
std::string filename(fname ? fname : "");

// Invoke the target factory to create a proxy_deserialize by opening the file.
dlib::proxy_deserialize tmp_proxy = dlib::deserialize(filename);

// Move the proxy object to the heap so the fuzzer runtime can persist it as an output.
dlib::proxy_deserialize* proxy = new dlib::proxy_deserialize(std::move(tmp_proxy));

// Validation: Construction may throw inside dlib::deserialize() if open fails; reaching here implies a valid proxy.
// OK

// Prepare a writable stream and a random byte value to pack.
std::ostringstream out;
unsigned int byte_u = *FUZZ_PARAM(unsigned int);
char ch = static_cast<char>(byte_u & 0xFF);

bool failed = dlib::pack_byte(ch, out);
// The API returns false on success. If it indicates failure, bail this iteration.
if (failed) { FUZZ_BAIL(); }
// Validation: We do not assert stream contents; we only ensure API contract (false == success) is handled.
// OK

// Prepare a readable stream with at least 1 byte.
std::string src = FUZZ_PARAM_STR();
if (src.empty()) src.push_back(static_cast<char>(*FUZZ_PARAM(unsigned int) & 0xFF));
std::istringstream in(src);

unsigned char ch = 0;
bool failed = dlib::unpack_byte(ch, in);
// The API returns false on success. If it indicates failure/EOF, bail.
if (failed) { FUZZ_BAIL(); }
// Validation: Successfully read one byte and advanced the stream.
// OK

// Generate a random floating-point value and serialize it using dlib's portable format.
double val = *FUZZ_PARAM(double);
std::ostringstream out;
try {
    dlib::serialize_floating_point(val, out);
} catch (const dlib::serialization_error&) {
    FUZZ_BAIL();
}
// Validation: No further checks; reaching here means serialization succeeded and stream is writable.
// OK

// Construct an ASCII-formatted floating-point token terminated by a space, or special tokens.
std::ostringstream gen;
unsigned int mode = *FUZZ_PARAM(unsigned int) % 5;
if (mode == 0) { gen << "inf "; }
else if (mode == 1) { gen << "ninf "; }
else if (mode == 2) { gen << "NaN "; }
else if (mode == 3) { gen << std::to_string(*FUZZ_PARAM(int)) << ' '; }
else { gen << std::to_string(*FUZZ_PARAM(double)) << ' '; }
std::string payload = gen.str();
std::istringstream in(payload);

double out_val = 0;
bool failed = dlib::old_deserialize_floating_point(out_val, in);
// Returns false on success; bail on failure.
if (failed) { FUZZ_BAIL(); }
// Validation: Successfully parsed token from legacy format.
// OK

// Feed either the new binary format or the old ASCII format, chosen randomly.
unsigned int which = *FUZZ_PARAM(unsigned int) & 1;
std::string payload;
if (which == 0) {
    // New format: use serialize_floating_point to produce bytes.
    double val = *FUZZ_PARAM(double);
    std::ostringstream out;
    try { dlib::serialize_floating_point(val, out); }
    catch (const dlib::serialization_error&) { FUZZ_BAIL(); }
    payload = out.str();
} else {
    // Old ASCII format: numeric or special tokens terminated by a space.
    std::ostringstream gen;
    unsigned int mode = *FUZZ_PARAM(unsigned int) % 4;
    if (mode == 0) gen << "inf ";
    else if (mode == 1) gen << "ninf ";
    else if (mode == 2) gen << "NaN ";
    else gen << std::to_string(*FUZZ_PARAM(double)) << ' ';
    payload = gen.str();
}

std::istringstream in(payload);
double parsed = 0;
try {
    dlib::deserialize_floating_point(parsed, in);
} catch (const dlib::serialization_error&) {
    FUZZ_BAIL();
}
// Validation: Successful deserialization from either format.
// OK

// Serialize a parameter pack of simple types using ADL-found serialize() overloads.
int a = static_cast<int>(*FUZZ_PARAM(unsigned int));
double b = *FUZZ_PARAM(double);
std::string c = FUZZ_PARAM_STR();

std::ostringstream out;
try {
    dlib::serialize_these(out, a, b, c);
} catch (const dlib::serialization_error&) {
    FUZZ_BAIL();
}
// Validation: Stream now contains serialized representations of a, b, c in order.
// OK

// First, create a valid stream by serializing some values, then read them back with deserialize_these.
int a = static_cast<int>(*FUZZ_PARAM(unsigned int));
double b = *FUZZ_PARAM(double);
std::string c = FUZZ_PARAM_STR();

std::ostringstream out;
try {
    dlib::serialize_these(out, a, b, c);
} catch (const dlib::serialization_error&) {
    FUZZ_BAIL();
}

std::string payload = out.str();
std::istringstream in(payload);
int a2 = 0; double b2 = 0; std::string c2;
try {
    dlib::deserialize_these(in, a2, b2, c2);
} catch (const dlib::serialization_error&) {
    FUZZ_BAIL();
}
// Optionally assert properties for non-NaN values, but avoid strict equality for all doubles; just ensure flow completes.
// OK

// Build a proxy_serialize that writes into a vector-backed stream and then push a few serializable items.
std::vector<uint8_t> buf;
auto s = dlib::serialize(buf); // factory producing proxy_serialize
int a = static_cast<int>(*FUZZ_PARAM(unsigned int));
double b = *FUZZ_PARAM(double);
std::string c = FUZZ_PARAM_STR();

try {
    s << a << b << c; // target operator<< called repeatedly via chaining
} catch (const dlib::serialization_error&) {
    FUZZ_BAIL();
}
// Validation: No outputs; buffer now contains serialized a,b,c.
// OK

// Prepare a buffer with serialized objects, then construct a proxy_deserialize over it and read them back.
std::vector<uint8_t> buf;
{
    auto s = dlib::serialize(buf);
    int a = static_cast<int>(*FUZZ_PARAM(unsigned int));
    double b = *FUZZ_PARAM(double);
    std::string c = FUZZ_PARAM_STR();
    try { s << a << b << c; } catch (const dlib::serialization_error&) { FUZZ_BAIL(); }
}

// Construct proxy_deserialize using its vectorstream-based constructor.
dlib::proxy_deserialize pd(buf);

int out_a = 0; double out_b = 0; std::string out_c;
try {
    pd >> out_a >> out_b >> out_c; // target operator>>
} catch (const dlib::serialization_error&) {
    // Any parse error should bail this case.
    FUZZ_BAIL();
}
// Validation: Successfully read three objects from the proxy stream.
// OK

