import random
import struct
from typing import Optional

# Generator for a dlib-serialized sequence: int, double, string
# Assumptions about dlib formats (sufficient for these fuzz stubs):
# - int: zigzag-encoded signed 64-bit integer, emitted as base-128 varint
# - double: new-format binary using a leading 0xFF marker then little-endian IEEE-754 8 bytes
# - std::string: varint length followed by raw bytes

MAX_TOTAL_SIZE = 4096


def _u64_varint(n: int) -> bytes:
    out = bytearray()
    while True:
        b = n & 0x7F
        n >>= 7
        if n:
            out.append(b | 0x80)
        else:
            out.append(b)
            break
    return bytes(out)


def _zigzag(i: int) -> int:
    # Zigzag for signed 64-bit
    return ((i & 0xFFFFFFFFFFFFFFFF) << 1) ^ (((i & 0xFFFFFFFFFFFFFFFF) >> 63) & 1)


def _encode_int(i: int) -> bytes:
    # Clamp to signed 64-bit
    if i < -0x8000000000000000:
        i = -0x8000000000000000
    if i > 0x7FFFFFFFFFFFFFFF:
        i = 0x7FFFFFFFFFFFFFFF
    u = _zigzag(i)
    return _u64_varint(u)


def _encode_double(d: float) -> bytes:
    # New-format binary: marker 0xFF + 8-byte LE double
    return b"\xFF" + struct.pack("<d", d)


def _encode_string(s: bytes) -> bytes:
    return _u64_varint(len(s)) + s


def _pick_interesting_int(rng: random.Random) -> int:
    choices = [
        0, 1, -1,
        127, 128, 255, 256,
        16383, 16384, 65535, 65536,
        2**31 - 1, -2**31,
        2**63 - 1, -2**63,
    ]
    if rng.random() < 0.6:
        return rng.choice(choices)
    return rng.randrange(-2**63, 2**63)


def _pick_interesting_double(rng: random.Random) -> float:
    specials = [0.0, -0.0, 1.0, -1.0, 0.5, -0.5, float('inf'), float('-inf'), float('nan')]
    if rng.random() < 0.5:
        return rng.choice(specials)
    sign = -1.0 if rng.getrandbits(1) else 1.0
    exp = rng.randint(-1022, 1023)
    mant = rng.random()
    return sign * mant * (2.0 ** exp)


def _pick_interesting_string(rng: random.Random) -> bytes:
    parts = []
    ascii_samples = [
        b"hello", b"", b"dlib", b"serialization", b"test", b"\x00",
        b"line1\nline2\r\nend", b"spaces    tabs\t\t", b"unicode:",
    ]
    parts.append(rng.choice(ascii_samples))

    # Add some UTF-8 sequences without embedding literal NULs in source
    utf8_candidates = [
        "\u00A9",  # copyright
        "\u20AC",  # euro
        "\u2603",  # snowman
        "\u03B1\u03B2\u03B3",  # greek alpha beta gamma
        "\U0001F600",  # grinning face
        "\u0000",  # NUL via escape
        "\u007F",  # DEL
        "\u001F",  # unit separator
    ]
    if rng.random() < 0.7:
        s = rng.choice(utf8_candidates).encode('utf-8', errors='strict')
        parts.append(s)

    # Binary random bytes
    if rng.random() < 0.7:
        bin_len = rng.randint(0, 64)
        parts.append(bytes(rng.getrandbits(8) for _ in range(bin_len)))

    # Repeated patterns
    if rng.random() < 0.5:
        pat = rng.choice([b"A", b"\x00", b"\xFF\x00"]) * rng.randint(1, 64)
        parts.append(pat)

    data = b"".join(parts)
    if len(data) > 1024:
        data = data[:1024]
    return data


def _build_sequence(i: int, d: float, s: bytes) -> bytes:
    return _encode_int(i) + _encode_double(d) + _encode_string(s)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    i = _pick_interesting_int(rng)
    d = _pick_interesting_double(rng)
    s = _pick_interesting_string(rng)

    payload = _build_sequence(i, d, s)

    if len(payload) > MAX_TOTAL_SIZE:
        max_s_len = max(0, MAX_TOTAL_SIZE - (len(_encode_int(i)) + len(_encode_double(d)) + 10))
        s = s[:max_s_len]
        payload = _build_sequence(i, d, s)

    return payload
